(()=>{document.documentElement.style.setProperty('--orange','#f26a32');document.querySelector('#searchToggle')?.remove();const esc=s=>String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const defaults=[{id:'1',title:'Ev tadilatı bütçesi nasıl hazırlanır?',category:'Maliyet & Bütçe',excerpt:'Doğru keşif ve iş sıralaması ile bütçenizi kontrol altında tutun.',content:'Tadilat bütçesi hazırlarken işe ihtiyaç listesini netleştirerek başlayın.',image:'assets/blog-kayseri.jpg',date:'03 Ekim 2026'}];async function get(){try{let r=await fetch('/api/posts');if(r.ok)return await r.json()}catch(_){}return JSON.parse(localStorage.getItem('prokont_blog_posts')||JSON.stringify(defaults))}get().then(a=>{let list=document.querySelector('#posts');if(!list)return;let card=p=>`<article class="post-card"><div class="post-image" style="background-image:url('${esc(p.image)}')"></div><div class="post-body"><small>${esc(p.category)} · ${esc(p.date)}</small><h3>${esc(p.title)}</h3><p>${esc(p.excerpt)}</p><button data-id="${p.id}">Yazıyı oku →</button></div></article>`,draw=x=>list.innerHTML=x.map(card).join('');draw(a);document.querySelector('#categoryFilters').innerHTML=['Tümü',...new Set(a.map(x=>x.category))].map(x=>`<button>${esc(x)}</button>`).join('');list.onclick=e=>{let p=a.find(x=>x.id===e.target.dataset.id);if(!p)return;let d=document.createElement('dialog');d.className='post-dialog';d.innerHTML=`<button class="close-dialog">Kapat ×</button><small>${esc(p.category)} · ${esc(p.date)}</small><h2>${esc(p.title)}</h2><p>${esc(p.content)}</p>${(p.attachments||[]).map(x=>`<p><a href="${esc(x.url)}" download>📎 ${esc(x.name)}</a></p>`).join('')}`;document.body.append(d);d.showModal();d.querySelector('button').onclick=()=>d.close()};document.querySelector('#blogSearch').oninput=e=>draw(a.filter(x=>(x.title+x.excerpt+x.tags).toLocaleLowerCase('tr').includes(e.target.value.toLocaleLowerCase('tr'))))})})();
